export const TEAM_ASSIGNMENTS_BASKET = {
  getPlayersByTeam: (teamName: string) => PLAYERS_BASKET.filter(p => p.equipo === teamName),
  getTeamByName: (teamName: string) => TEAMS_BASKET.find(t => t.name === teamName),
  getCoachById: (id: string) => COACHES_BASKET.find(c => c.id === id)
};
